class Point { public int X; public int Y { get; set; } }
class Holder {
    public readonly Point Point = new Point();
    public int Reads;
    public Point Current { get { Reads++; Print("getter"); return Point; } }
}
void Main() {
    var holder = new Holder { Current = { X = 2, Y = 3 } };
    Print(holder.Point.X); Print(holder.Point.Y); Print(holder.Reads);
    var empty = new Holder { Current = {} }; Print(empty.Reads);
    var replaced = new Holder { Point = { X = 4, Y = 5 } }; Print(replaced.Point.X + replaced.Point.Y);
}
